CREATE DATABASE IF NOT EXISTS db_maso;
USE db_maso;

DROP TABLE IF EXISTS users;
CREATE TABLE users (
  id INT PRIMARY KEY,
  nama VARCHAR(100),
  username VARCHAR(50),
  password VARCHAR(100),
  domisili VARCHAR(100),
  umur INT,
  kelamin VARCHAR(20),
  hobi VARCHAR(150),
  tujuan VARCHAR(50),
  deskripsi TEXT
);

